-- South Korea story arc: 3 stories tracing the e-Tax Invoice system
-- from its 2011 corporate launch through the 2023 self-billing
-- introduction to the 2024 threshold reaching its lowest-ever level.
-- Sourced from Sovos's dedicated e-Tax Invoice history page,
-- Storecove, and VATupdate's July 2026 country booklet, cross-checked
-- against each other for dates and figures.

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2011-01-15-south-korea-corporate-mandate', '2011-01-15', '2011-01', 'South Korea required all corporate taxpayers to issue VAT invoices electronically and report them to the National Tax Service by the next business day -- the start of what is now the longest-running e-invoicing mandate covered anywhere in this tracker.', '<h3>🇰🇷 South Korea''s e-Tax Invoice becomes mandatory for all corporations</h3>
<p>The National Tax Service (NTS) began requiring every corporate taxpayer in South Korea to issue Value-Added Tax invoices electronically, in XML format with a digital signature, and to transmit them to the NTS by the next business day. Unlike the clearance-model mandates common in the Middle East and parts of Latin America, this is a post-issuance reporting model: the invoice takes legal effect the moment it reaches the buyer, and next-day transmission to the NTS is a separate reporting duty rather than a precondition for the invoice''s validity.</p>
<p>Businesses can transmit through the free NTS Hometax portal, a certified ASP, an in-house accounting system with a digital certificate, an automated telephone system, or in person at a tax office -- a five-channel design that would remain largely unchanged for the next decade and a half.</p>
<p>For every Korean corporation, e-invoicing has been the norm, not the exception, ever since -- this is the foundation the mandate''s later threshold-driven expansion to individual entrepreneurs builds on.</p>', 'https://sovos.com/vat/tax-rules/electronic-tax-invoices-south-korea/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2011-01-15-south-korea-corporate-mandate', id FROM countries WHERE name_en = 'South Korea';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2011-01-15-south-korea-corporate-mandate', 'en', 'South Korea''s e-Tax Invoice becomes mandatory for all corporations', 'South Korea required all corporate taxpayers to issue VAT invoices electronically and report them to the National Tax Service by the next business day -- the start of what is now the longest-running e-invoicing mandate covered anywhere in this tracker.', '<h3>🇰🇷 South Korea''s e-Tax Invoice becomes mandatory for all corporations</h3>
<p>The National Tax Service (NTS) began requiring every corporate taxpayer in South Korea to issue Value-Added Tax invoices electronically, in XML format with a digital signature, and to transmit them to the NTS by the next business day. Unlike the clearance-model mandates common in the Middle East and parts of Latin America, this is a post-issuance reporting model: the invoice takes legal effect the moment it reaches the buyer, and next-day transmission to the NTS is a separate reporting duty rather than a precondition for the invoice''s validity.</p>
<p>Businesses can transmit through the free NTS Hometax portal, a certified ASP, an in-house accounting system with a digital certificate, an automated telephone system, or in person at a tax office -- a five-channel design that would remain largely unchanged for the next decade and a half.</p>
<p>For every Korean corporation, e-invoicing has been the norm, not the exception, ever since -- this is the foundation the mandate''s later threshold-driven expansion to individual entrepreneurs builds on.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2011-01-15-south-korea-corporate-mandate', 'es', 'La e-Tax Invoice de Corea del Sur se vuelve obligatoria para todas las corporaciones', 'Corea del Sur exigió a todos los contribuyentes corporativos emitir facturas del IVA electrónicamente y reportarlas al Servicio Nacional de Impuestos antes del siguiente día hábil -- el inicio de lo que hoy es el mandato de facturación electrónica de mayor duración de todo este seguimiento.', '<h3>🇰🇷 La e-Tax Invoice de Corea del Sur se vuelve obligatoria para todas las corporaciones</h3>
<p>El Servicio Nacional de Impuestos (NTS) comenzó a exigir a todo contribuyente corporativo en Corea del Sur que emitiera facturas del Impuesto al Valor Agregado electrónicamente, en formato XML con firma digital, y que las transmitiera al NTS antes del siguiente día hábil. A diferencia de los mandatos de modelo de validación habituales en Oriente Medio y partes de Latinoamérica, este es un modelo de reporte posterior a la emisión: la factura surte efecto legal en el momento en que llega al comprador, y la transmisión al NTS al día siguiente es una obligación de reporte independiente, no una condición previa para la validez de la factura.</p>
<p>Las empresas pueden transmitir a través del portal gratuito NTS Hometax, un ASP certificado, un sistema contable interno con certificado digital, un sistema telefónico automatizado, o en persona en una oficina tributaria -- un diseño de cinco canales que permanecería prácticamente sin cambios durante la siguiente década y media.</p>
<p>Para toda corporación coreana, la facturación electrónica ha sido la norma, no la excepción, desde entonces -- esta es la base sobre la que se construye la expansión posterior del mandato a los empresarios individuales impulsada por umbrales.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2011-01-15-south-korea-corporate-mandate', 'de', 'Südkoreas e-Tax Invoice wird für alle Kapitalgesellschaften verpflichtend', 'Südkorea verpflichtete alle körperschaftsteuerpflichtigen Unternehmen, Mehrwertsteuerrechnungen elektronisch auszustellen und bis zum nächsten Werktag an die nationale Steuerbehörde zu melden -- der Beginn der heute am längsten laufenden Pflicht zur elektronischen Rechnungsstellung in diesem gesamten Tracker.', '<h3>🇰🇷 Südkoreas e-Tax Invoice wird für alle Kapitalgesellschaften verpflichtend</h3>
<p>Die nationale Steuerbehörde (NTS) verlangte fortan von jedem körperschaftsteuerpflichtigen Unternehmen in Südkorea, Mehrwertsteuerrechnungen elektronisch im XML-Format mit digitaler Signatur auszustellen und bis zum nächsten Werktag an die NTS zu übermitteln. Anders als bei den im Nahen Osten und Teilen Lateinamerikas verbreiteten Freigabemodell-Pflichten handelt es sich um ein Meldemodell nach Rechnungsausstellung: Die Rechnung wird rechtswirksam, sobald sie den Käufer erreicht, und die Übermittlung an die NTS am nächsten Tag ist eine gesonderte Meldepflicht, keine Voraussetzung für die Gültigkeit der Rechnung.</p>
<p>Unternehmen können über das kostenlose NTS-Hometax-Portal, einen zertifizierten ASP, ein internes Buchhaltungssystem mit digitalem Zertifikat, ein automatisiertes Telefonsystem oder persönlich bei einem Finanzamt übermitteln -- ein Fünf-Kanal-Design, das für die folgenden anderthalb Jahrzehnte weitgehend unverändert bleiben sollte.</p>
<p>Für jede koreanische Kapitalgesellschaft ist die elektronische Rechnungsstellung seither die Norm, nicht die Ausnahme -- dies ist die Grundlage, auf der die spätere, schwellenwertgetriebene Ausweitung der Pflicht auf Einzelunternehmer aufbaut.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2011-01-15-south-korea-corporate-mandate', 'fr', 'La e-Tax Invoice de la Corée du Sud devient obligatoire pour toutes les sociétés', 'La Corée du Sud a exigé de tous les contribuables constitués en société qu''ils émettent des factures de TVA électroniquement et les déclarent à l''Administration fiscale nationale au plus tard le jour ouvré suivant -- le début de ce qui est aujourd''hui l''obligation de facturation électronique la plus ancienne couverte par ce suivi.', '<h3>🇰🇷 La e-Tax Invoice de la Corée du Sud devient obligatoire pour toutes les sociétés</h3>
<p>L''Administration fiscale nationale (NTS) a commencé à exiger de chaque contribuable constitué en société en Corée du Sud qu''il émette des factures de taxe sur la valeur ajoutée électroniquement, au format XML avec une signature numérique, et les transmette à la NTS au plus tard le jour ouvré suivant. Contrairement aux obligations à modèle de validation courantes au Moyen-Orient et dans certaines parties d''Amérique latine, il s''agit d''un modèle de déclaration postérieure à l''émission : la facture prend effet juridique dès qu''elle atteint l''acheteur, et la transmission à la NTS le lendemain constitue une obligation déclarative distincte, non une condition préalable à la validité de la facture.</p>
<p>Les entreprises peuvent transmettre via le portail gratuit NTS Hometax, un ASP certifié, un système comptable interne avec certificat numérique, un système téléphonique automatisé, ou en personne dans un bureau des impôts -- une conception à cinq canaux qui allait rester largement inchangée pendant la décennie et demie suivante.</p>
<p>Pour chaque société coréenne, la facturation électronique est depuis la norme, et non l''exception -- c''est le fondement sur lequel s''appuie l''extension ultérieure de l''obligation, pilotée par seuil, aux entrepreneurs individuels.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2023-07-15-south-korea-self-billing-threshold-100m', '2023-07-15', '2023-07', 'South Korea lowered the individual-entrepreneur e-Tax Invoice threshold to KRW 100 million and introduced self-billing invoices, letting buyers create a compliant invoice when their supplier is unable to.', '<h3>🇰🇷 Threshold falls to KRW 100 million; self-billing invoices arrive</h3>
<p>The revenue threshold bringing individual entrepreneurs (sole proprietors) into South Korea''s mandatory e-Tax Invoice system fell again, from KRW 200 million to KRW 100 million in prior-year supply -- part of a sustained, decade-long push toward near-universal coverage that began with corporations in 2011.</p>
<p>Alongside the threshold cut, the National Tax Service introduced self-billing invoices: where a supplier is genuinely unable to issue an e-Tax Invoice, the buyer may create one instead for VAT-taxable supplies, subject to confirmation by a district tax office. This closes a real gap for buyers who would otherwise have no compliant invoice to rely on for their own input-VAT deduction.</p>
<p>For individual entrepreneurs newly caught by the lower threshold, this was the point to start issuing e-Tax Invoices in earnest -- and for their business customers, a reminder to check supplier compliance rather than simply assume it.</p>', 'https://www.storecove.com/blog/en/e-invoicing-in-south-korea-regulations/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2023-07-15-south-korea-self-billing-threshold-100m', id FROM countries WHERE name_en = 'South Korea';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2023-07-15-south-korea-self-billing-threshold-100m', 'en', 'Threshold falls to KRW 100 million; self-billing invoices arrive', 'South Korea lowered the individual-entrepreneur e-Tax Invoice threshold to KRW 100 million and introduced self-billing invoices, letting buyers create a compliant invoice when their supplier is unable to.', '<h3>🇰🇷 Threshold falls to KRW 100 million; self-billing invoices arrive</h3>
<p>The revenue threshold bringing individual entrepreneurs (sole proprietors) into South Korea''s mandatory e-Tax Invoice system fell again, from KRW 200 million to KRW 100 million in prior-year supply -- part of a sustained, decade-long push toward near-universal coverage that began with corporations in 2011.</p>
<p>Alongside the threshold cut, the National Tax Service introduced self-billing invoices: where a supplier is genuinely unable to issue an e-Tax Invoice, the buyer may create one instead for VAT-taxable supplies, subject to confirmation by a district tax office. This closes a real gap for buyers who would otherwise have no compliant invoice to rely on for their own input-VAT deduction.</p>
<p>For individual entrepreneurs newly caught by the lower threshold, this was the point to start issuing e-Tax Invoices in earnest -- and for their business customers, a reminder to check supplier compliance rather than simply assume it.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2023-07-15-south-korea-self-billing-threshold-100m', 'es', 'El umbral baja a 100 millones de KRW; llegan las facturas de autofacturación', 'Corea del Sur bajó el umbral de e-Tax Invoice para empresarios individuales a 100 millones de KRW e introdujo las facturas de autofacturación, permitiendo a los compradores crear una factura conforme cuando su proveedor no puede hacerlo.', '<h3>🇰🇷 El umbral baja a 100 millones de KRW; llegan las facturas de autofacturación</h3>
<p>El umbral de ingresos que incorpora a los empresarios individuales (autónomos) al sistema obligatorio de e-Tax Invoice de Corea del Sur volvió a bajar, de 200 millones de KRW a 100 millones de KRW de suministro del año anterior -- parte de un impulso sostenido de una década hacia una cobertura casi universal que comenzó con las corporaciones en 2011.</p>
<p>Junto con la reducción del umbral, el Servicio Nacional de Impuestos introdujo las facturas de autofacturación: cuando un proveedor genuinamente no puede emitir una e-Tax Invoice, el comprador puede crear una en su lugar para suministros sujetos al IVA, sujeto a confirmación por una oficina tributaria de distrito. Esto cierra una brecha real para los compradores que de otro modo no tendrían ninguna factura conforme en la que basarse para su propia deducción del IVA soportado.</p>
<p>Para los empresarios individuales recién alcanzados por el umbral más bajo, este fue el momento de empezar a emitir e-Tax Invoice en serio -- y para sus clientes empresariales, un recordatorio de verificar el cumplimiento de sus proveedores en lugar de simplemente asumirlo.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2023-07-15-south-korea-self-billing-threshold-100m', 'de', 'Schwellenwert sinkt auf 100 Millionen KRW; Selbstfakturierung eingeführt', 'Südkorea senkte den e-Tax-Invoice-Schwellenwert für Einzelunternehmer auf 100 Millionen KRW und führte die Selbstfakturierung ein, die es Käufern erlaubt, eine konforme Rechnung zu erstellen, wenn ihr Lieferant dazu nicht in der Lage ist.', '<h3>🇰🇷 Schwellenwert sinkt auf 100 Millionen KRW; Selbstfakturierung eingeführt</h3>
<p>Der Umsatzschwellenwert, der Einzelunternehmer in Südkoreas verpflichtendes e-Tax-Invoice-System einbezieht, sank erneut, von 200 Millionen KRW auf 100 Millionen KRW des Vorjahresumsatzes -- Teil eines seit einem Jahrzehnt anhaltenden Vorstoßes hin zu einer nahezu universellen Abdeckung, der 2011 mit den Kapitalgesellschaften begann.</p>
<p>Zusammen mit der Schwellenwertsenkung führte die nationale Steuerbehörde die Selbstfakturierung ein: Kann ein Lieferant tatsächlich keine e-Tax Invoice ausstellen, darf der Käufer stattdessen selbst eine für umsatzsteuerpflichtige Lieferungen erstellen, vorbehaltlich der Bestätigung durch ein Bezirksfinanzamt. Dies schließt eine echte Lücke für Käufer, die sonst keine konforme Rechnung für ihren eigenen Vorsteuerabzug hätten.</p>
<p>Für Einzelunternehmer, die durch den niedrigeren Schwellenwert neu erfasst wurden, war dies der Zeitpunkt, ernsthaft mit der Ausstellung von e-Tax Invoices zu beginnen -- und für ihre Geschäftskunden eine Erinnerung, die Einhaltung durch Lieferanten zu prüfen, statt sie einfach anzunehmen.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2023-07-15-south-korea-self-billing-threshold-100m', 'fr', 'Le seuil baisse à 100 millions de KRW ; l''autofacturation fait son apparition', 'La Corée du Sud a abaissé le seuil e-Tax Invoice pour les entrepreneurs individuels à 100 millions de KRW et a introduit l''autofacturation, permettant aux acheteurs de créer une facture conforme lorsque leur fournisseur ne le peut pas.', '<h3>🇰🇷 Le seuil baisse à 100 millions de KRW ; l''autofacturation fait son apparition</h3>
<p>Le seuil de revenu faisant entrer les entrepreneurs individuels dans le système obligatoire de e-Tax Invoice de la Corée du Sud a de nouveau baissé, passant de 200 millions de KRW à 100 millions de KRW de fourniture de l''année précédente -- élément d''une poussée soutenue sur une décennie vers une couverture quasi universelle, amorcée avec les sociétés en 2011.</p>
<p>Parallèlement à cette baisse de seuil, l''Administration fiscale nationale a introduit l''autofacturation : lorsqu''un fournisseur est véritablement dans l''incapacité d''émettre une e-Tax Invoice, l''acheteur peut en créer une à sa place pour les fournitures soumises à la TVA, sous réserve de confirmation par un bureau des impôts de district. Cela comble un véritable vide pour les acheteurs qui, sinon, n''auraient aucune facture conforme sur laquelle s''appuyer pour leur propre déduction de TVA en amont.</p>
<p>Pour les entrepreneurs individuels nouvellement concernés par le seuil abaissé, c''était le moment de commencer à émettre sérieusement des e-Tax Invoice -- et pour leurs clients professionnels, un rappel de vérifier la conformité des fournisseurs plutôt que de simplement la supposer.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2024-07-15-south-korea-threshold-80m', '2024-07-15', '2024-07', 'South Korea''s individual-entrepreneur e-Tax Invoice threshold fell to KRW 80 million, the lowest level since the mandate first extended beyond corporations in 2012.', '<h3>🇰🇷 Threshold reaches its lowest-ever level: KRW 80 million</h3>
<p>The revenue threshold bringing individual entrepreneurs into South Korea''s e-Tax Invoice mandate fell again, from KRW 100 million to KRW 80 million in prior-year supply -- the fifth reduction since individual entrepreneurs were first brought into scope in 2012 at KRW 1 billion, and the lowest figure yet.</p>
<p>The trend is unmistakable: 1 billion → 300 million → 200 million → 100 million → 80 million KRW, each cut widening the mandate''s reach without any change to the underlying corporate mandate, which has stood unmodified since 2011. Industry compliance guides widely expect further reductions to continue, though no additional specific date has been legislated yet.</p>
<p>For individual entrepreneurs near this threshold, the message is the same each time it falls: check your prior-year supply value against the current figure directly, rather than relying on a number from a few years ago that may no longer apply.</p>', 'https://sovos.com/vat/tax-rules/electronic-tax-invoices-south-korea/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2024-07-15-south-korea-threshold-80m', id FROM countries WHERE name_en = 'South Korea';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-07-15-south-korea-threshold-80m', 'en', 'Threshold reaches its lowest-ever level: KRW 80 million', 'South Korea''s individual-entrepreneur e-Tax Invoice threshold fell to KRW 80 million, the lowest level since the mandate first extended beyond corporations in 2012.', '<h3>🇰🇷 Threshold reaches its lowest-ever level: KRW 80 million</h3>
<p>The revenue threshold bringing individual entrepreneurs into South Korea''s e-Tax Invoice mandate fell again, from KRW 100 million to KRW 80 million in prior-year supply -- the fifth reduction since individual entrepreneurs were first brought into scope in 2012 at KRW 1 billion, and the lowest figure yet.</p>
<p>The trend is unmistakable: 1 billion → 300 million → 200 million → 100 million → 80 million KRW, each cut widening the mandate''s reach without any change to the underlying corporate mandate, which has stood unmodified since 2011. Industry compliance guides widely expect further reductions to continue, though no additional specific date has been legislated yet.</p>
<p>For individual entrepreneurs near this threshold, the message is the same each time it falls: check your prior-year supply value against the current figure directly, rather than relying on a number from a few years ago that may no longer apply.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-07-15-south-korea-threshold-80m', 'es', 'El umbral alcanza su nivel más bajo hasta la fecha: 80 millones de KRW', 'El umbral de e-Tax Invoice para empresarios individuales de Corea del Sur bajó a 80 millones de KRW, el nivel más bajo desde que el mandato se extendió por primera vez más allá de las corporaciones en 2012.', '<h3>🇰🇷 El umbral alcanza su nivel más bajo hasta la fecha: 80 millones de KRW</h3>
<p>El umbral de ingresos que incorpora a los empresarios individuales al mandato de e-Tax Invoice de Corea del Sur volvió a bajar, de 100 millones de KRW a 80 millones de KRW de suministro del año anterior -- la quinta reducción desde que los empresarios individuales entraron por primera vez en el ámbito de aplicación en 2012 con 1.000 millones de KRW, y la cifra más baja hasta la fecha.</p>
<p>La tendencia es inconfundible: 1.000 millones → 300 millones → 200 millones → 100 millones → 80 millones de KRW, cada recorte ampliando el alcance del mandato sin ningún cambio en el mandato corporativo subyacente, que se ha mantenido sin modificaciones desde 2011. Las guías de cumplimiento del sector esperan ampliamente que continúen nuevas reducciones, aunque todavía no se ha legislado ninguna fecha específica adicional.</p>
<p>Para los empresarios individuales cercanos a este umbral, el mensaje es el mismo cada vez que baja: compruebe su valor de suministro del año anterior frente a la cifra actual directamente, en lugar de confiar en un número de hace unos años que puede que ya no se aplique.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-07-15-south-korea-threshold-80m', 'de', 'Schwellenwert erreicht bisheriges Allzeittief: 80 Millionen KRW', 'Südkoreas e-Tax-Invoice-Schwellenwert für Einzelunternehmer sank auf 80 Millionen KRW -- das niedrigste Niveau, seit die Pflicht 2012 erstmals über Kapitalgesellschaften hinaus ausgeweitet wurde.', '<h3>🇰🇷 Schwellenwert erreicht bisheriges Allzeittief: 80 Millionen KRW</h3>
<p>Der Umsatzschwellenwert, der Einzelunternehmer in Südkoreas e-Tax-Invoice-Pflicht einbezieht, sank erneut, von 100 Millionen KRW auf 80 Millionen KRW des Vorjahresumsatzes -- die fünfte Senkung, seit Einzelunternehmer 2012 erstmals mit 1 Milliarde KRW einbezogen wurden, und der bisher niedrigste Wert.</p>
<p>Der Trend ist unverkennbar: 1 Milliarde → 300 Millionen → 200 Millionen → 100 Millionen → 80 Millionen KRW, wobei jede Senkung die Reichweite der Pflicht vergrößert, ohne dass sich an der zugrunde liegenden Unternehmenspflicht, die seit 2011 unverändert besteht, etwas geändert hätte. Branchenübliche Compliance-Leitfäden erwarten weitgehend weitere Senkungen, wenngleich noch kein weiteres konkretes Datum gesetzlich festgelegt wurde.</p>
<p>Für Einzelunternehmer nahe diesem Schwellenwert bleibt die Botschaft bei jeder Senkung gleich: Vergleichen Sie Ihren Vorjahresumsatz direkt mit der aktuellen Zahl, statt sich auf eine Zahl von vor einigen Jahren zu verlassen, die möglicherweise nicht mehr gilt.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-07-15-south-korea-threshold-80m', 'fr', 'Le seuil atteint son niveau le plus bas à ce jour : 80 millions de KRW', 'Le seuil e-Tax Invoice pour les entrepreneurs individuels de la Corée du Sud est tombé à 80 millions de KRW, le niveau le plus bas depuis que l''obligation s''est étendue pour la première fois au-delà des sociétés en 2012.', '<h3>🇰🇷 Le seuil atteint son niveau le plus bas à ce jour : 80 millions de KRW</h3>
<p>Le seuil de revenu faisant entrer les entrepreneurs individuels dans l''obligation e-Tax Invoice de la Corée du Sud a de nouveau baissé, passant de 100 millions de KRW à 80 millions de KRW de fourniture de l''année précédente -- la cinquième réduction depuis que les entrepreneurs individuels sont entrés dans le champ d''application en 2012 à 1 milliard de KRW, et le chiffre le plus bas à ce jour.</p>
<p>La tendance est sans équivoque : 1 milliard → 300 millions → 200 millions → 100 millions → 80 millions de KRW, chaque baisse élargissant la portée de l''obligation sans aucun changement à l''obligation des sociétés sous-jacente, restée inchangée depuis 2011. Les guides de conformité du secteur s''attendent largement à ce que d''autres réductions se poursuivent, bien qu''aucune autre date précise n''ait encore été légiférée.</p>
<p>Pour les entrepreneurs individuels proches de ce seuil, le message reste le même à chaque baisse : vérifiez votre valeur de fourniture de l''année précédente par rapport au chiffre actuel directement, plutôt que de vous fier à un chiffre datant de quelques années qui pourrait ne plus s''appliquer.</p>');
